argv:
$ErrorActionPreference='Stop'
$t=Invoke-RestMethod -UseBasicParsing 'http://127.0.0.1:17410/json/list' -TimeoutSec 3
$target=@($t)|Where-Object { try { ([uri]$_.url).Host -eq 'bugbountyfoto6.files.com' } catch { $false } } | Select-Object -First 1
$ws=[Net.WebSockets.ClientWebSocket]::new();$cts=[Threading.CancellationTokenSource]::new();$cts.CancelAfter(6500)
$ws.ConnectAsync([uri]$target.webSocketDebuggerUrl,$cts.Token).GetAwaiter().GetResult()|Out-Null
$expr=@'
(()=>{
 const ds=[...document.querySelectorAll('[role="dialog"]')];
 const d=ds.find(x=>(x.innerText||'').includes('Move Source'));
 if(!d)return JSON.stringify({error:'Move dialog not found'});
 const all=[...d.querySelectorAll('*')].map((e,i)=>({
   i,tag:e.tagName,role:e.getAttribute('role'),text:(e.innerText||e.getAttribute('aria-label')||'').trim().replace(/\s+/g,' ').slice(0,160),
   aria:e.getAttribute('aria-label'),tab:e.getAttribute('tabindex'),expanded:e.getAttribute('aria-expanded'),selected:e.getAttribute('aria-selected'),cls:(e.className||'').toString().slice(0,120)
 })).filter(x=>x.text && (x.role||x.tag==='BUTTON'||x.tag==='A'||x.tab==='0'||/folder|tree/i.test(x.cls)));
 return JSON.stringify(all.slice(0,140));
})()
'@
$payload=@{id=1;method='Runtime.evaluate';params=@{expression=$expr;returnByValue=$true}}|ConvertTo-Json -Depth 10 -Compress
$bytes=[Text.Encoding]::UTF8.GetBytes($payload)
$ws.SendAsync([ArraySegment[byte]]::new($bytes),[Net.WebSockets.WebSocketMessageType]::Text,$true,$cts.Token).GetAwaiter().GetResult()|Out-Null
$buf=New-Object byte[] 131072
while($true){$ms=[IO.MemoryStream]::new();do{$r=$ws.ReceiveAsync([ArraySegment[byte]]::new($buf),$cts.Token).GetAwaiter().GetResult();if($r.Count){$ms.Write($buf,0,$r.Count)}}while(-not $r.EndOfMessage);$o=([Text.Encoding]::UTF8.GetString($ms.ToArray())|ConvertFrom-Json);if($o.id -eq 1){Write-Output $o.result.result.value;break}}
$ws.Dispose()
